'use strict';
const D=window.DASHBOARD_DATA, NEWS=window.NEWS_DATA;
const $=id=>document.getElementById(id);
const fmt=(v,d=0)=>v===null||v===undefined||!Number.isFinite(v)?'—':v.toLocaleString('th-TH',{maximumFractionDigits:d,minimumFractionDigits:d});
const sum=(rows,k)=>rows.reduce((s,r)=>s+(Number(r[k])||0),0);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shortDate=s=>s?`${Number(s.slice(8,10))}/${Number(s.slice(5,7))}/${s.slice(0,4)}`:'—';
const thMonth=s=>`${['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'][Number(s.slice(5,7))-1]} ${s.slice(0,4)}`;
const million=v=>fmt(v/1e6,1);
const catNames={'Government policy & news':'นโยบายรัฐและข่าวสาร','Health products':'ผลิตภัณฑ์สุขภาพ','Finance & stocks':'การเงินและหุ้น','Disasters':'ภัยพิบัติ','Public order & security':'ความสงบและความมั่นคง','Economy':'เศรษฐกิจ','Drugs':'ยาเสพติด','Online crime':'ภัยออนไลน์','Other news':'ข่าวอื่น ๆ'};
const riskNames={'Misinformation':'ข้อมูลเท็จ','Malicious Actors & Misuse':'ผู้ประสงค์ร้ายและการใช้ผิดทาง','Discrimination and Toxicity':'การเลือกปฏิบัติและเนื้อหาเป็นพิษ','AI system safety, failures, and limitations':'ความปลอดภัยและข้อจำกัดระบบ','Privacy and Security':'ความเป็นส่วนตัวและความมั่นคง','Human-Computer Interaction':'ปฏิสัมพันธ์มนุษย์กับคอมพิวเตอร์','Socioeconomic and Environmental':'สังคม เศรษฐกิจ และสิ่งแวดล้อม'};
const colors=['#147f79','#e69c59','#628ba5','#a596ba','#b5a76e','#9aabb3','#cb7d7d'];
let tab='overview',selectedWeek=null;
$('start').value='2025-11-09';$('end').value='2026-10-18';
function card(title,sub,content,id=''){return `<article class="card"><div class="card-top"><h2>${title}</h2>${id?`<span class="card-id">${id}</span>`:''}</div><p class="subtitle">${sub}</p>${content}</article>`;}
function kpi(label,value,unit,note){return `<article class="kpi"><div class="kpi-label">${label}</div><div class="kpi-value">${value}<small>${unit}</small></div><div class="kpi-note">${note}</div></article>`;}
function empty(text='ไม่มีข้อมูลในช่วงที่เลือก'){return `<div class="empty">${text}</div>`;}
function tip(text){return `data-tip="${esc(text)}" tabindex="0"`;}
function bars(items,{percent=false,color='#147f79',unit='',height=35,left=180,width=620,decimals=0}={}){
 if(!items.length)return empty();
 const w=width,right=95,h=items.length*height+12,max=percent?100:Math.max(...items.map(r=>r.value),1),plot=w-left-right;
 let s=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="กราฟแท่งแนวนอน">`;
 items.forEach((r,i)=>{const y=i*height+8,bw=Math.max(0,r.value/max*plot);s+=`<text class="label" x="${left-12}" y="${y+14}" text-anchor="end">${esc(r.label)}</text><rect x="${left}" y="${y}" width="${plot}" height="20" rx="3" fill="#f1f5f5"/><rect ${tip(r.tip||`${r.label}\n${fmt(r.value,percent?1:decimals)} ${unit}`)} x="${left}" y="${y}" width="${bw}" height="20" rx="3" fill="${r.color||color}"/><text class="value" x="${left+plot+9}" y="${y+14}">${fmt(r.value,percent?1:decimals)}${unit}</text>`;});return `<div class="chart">${s}</svg></div>`;
}
function line(rows,key,color,label,{money=false,ratio=false}={}){
 const w=800,h=185,l=65,r=22,t=15,b=36,iw=w-l-r,ih=h-t-b,valid=rows.filter(x=>x[key]!=null);
 if(!valid.length)return empty('ไม่มีตัวเลขคดีที่ใช้คำนวณได้ในช่วงนี้');
 const max=Math.max(...valid.map(x=>x[key]),1)*1.1, x=i=>l+(rows.length===1?iw/2:i/(rows.length-1)*iw),y=v=>t+ih-v/max*ih;
 let s=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)}">`;
 for(let i=0;i<4;i++){const v=max*i/3,yy=y(v);s+=`<line class="gridline" x1="${l}" x2="${w-r}" y1="${yy}" y2="${yy}"/><text x="${l-10}" y="${yy+4}" text-anchor="end">${money?fmt(v/1e6,0):fmt(v,0)}</text>`;}
 let path='',active=false;
 rows.forEach((row,i)=>{if(row[key]==null){active=false;return;}path+=`${active?'L':'M'}${x(i).toFixed(1)},${y(row[key]).toFixed(1)} `;active=true;});
 s+=`<path d="${path}" fill="none" stroke="${color}" stroke-width="2.6" stroke-linejoin="round"/>`;
 rows.forEach((row,i)=>{if(row[key]==null)return;s+=`<circle cx="${x(i)}" cy="${y(row[key])}" r="2.5" fill="${color}"/><circle class="hit" data-week="${row.week_start}" ${tip(`สัปดาห์ ${shortDate(row.week_start)}–${shortDate(row.week_end)}\n${label}: ${fmt(row[key],ratio?1:0)} ${money||ratio?'บาท':'คดี'}${row.quality==='caution'?'\nมีหมายเหตุจากแหล่งข้อมูล':''}`)} cx="${x(i)}" cy="${y(row[key])}" r="8" fill="transparent"/>`;});
 [...new Set([0,Math.floor((rows.length-1)/3),Math.floor((rows.length-1)*2/3),rows.length-1])].forEach(i=>s+=`<text x="${x(i)}" y="${h-9}" text-anchor="middle">${shortDate(rows[i].week_start)}</text>`);
 return `<div class="legend"><span><i style="background:${color}"></i>${label}${money?' (ล้านบาท)':ratio?' (บาท)':''}</span></div><div class="chart">${s}</svg></div>`;
}
function monthly(rows){const m=new Map();for(const r of rows){if(!m.has(r.month))m.set(r.month,{month:r.month,fake:0,distorted:0,true:0});const x=m.get(r.month);x.fake+=r.afnc_fake;x.distorted+=r.afnc_distorted;x.true+=r.afnc_true;}return [...m.values()];}
function stacked(rows){
 if(!rows.length||!rows.some(r=>r.fake+r.distorted+r.true))return empty();
 const w=880,h=245,l=55,b=55,t=12,iw=w-l-18,ih=h-b-t,max=Math.max(...rows.map(r=>r.fake+r.distorted+r.true),1)*1.08,step=iw/rows.length,bw=Math.min(42,step*.67);
 let s=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="คำตัดสินข่าวรายเดือน">`;
 for(let i=0;i<4;i++){let v=max*i/3,yy=t+ih-v/max*ih;s+=`<line class="gridline" x1="${l}" x2="${w-18}" y1="${yy}" y2="${yy}"/><text x="${l-9}" y="${yy+4}" text-anchor="end">${fmt(v)}</text>`;}
 rows.forEach((r,i)=>{let base=t+ih;for(const [k,c] of [['fake','#147f79'],['distorted','#e69c59'],['true','#b6c8d0']]){const hh=r[k]/max*ih;base-=hh;s+=`<rect ${tip(`${thMonth(r.month)}\nข่าวปลอม ${fmt(r.fake)} · บิดเบือน ${fmt(r.distorted)} · ข่าวจริง ${fmt(r.true)}\nสัดส่วนข่าวเท็จ ${fmt(100*(r.fake+r.distorted)/(r.fake+r.distorted+r.true),1)}%`)} x="${l+i*step+(step-bw)/2}" y="${base}" width="${bw}" height="${hh}" fill="${c}"/>`;}
 if(i%Math.max(1,Math.ceil(rows.length/12))===0)s+=`<text x="${l+i*step+step/2}" y="${h-32}" text-anchor="middle" transform="rotate(-25 ${l+i*step+step/2} ${h-32})">${esc(thMonth(r.month))}</text>`;});
 return `<div class="legend"><span><i style="background:#147f79"></i>ข่าวปลอม</span><span><i style="background:#e69c59"></i>บิดเบือน</span><span><i style="background:#b6c8d0"></i>ข่าวจริง</span></div><div class="chart">${s}</svg></div>`;
}
function getRows(){return D.weekly.filter(r=>r.week_start>=$('start').value&&r.week_start<=$('end').value);}
function eligible(rows){return rows.filter(r=>r.acsc_reported&&($('include-flagged').checked||!r.exclude_default));}
function safeRows(rows){return rows.map(r=>r.acsc_reported&&($('include-flagged').checked||!r.exclude_default)?r:{...r,acsc_cases:null,acsc_loss_baht:null,acsc_loss_per_case_baht:null});}
function topWeeks(rows,key,money=false){return bars([...rows].sort((a,b)=>b[key]-a[key]).slice(0,5).map(r=>({label:shortDate(r.week_start),value:money?r[key]/1e6:r[key],tip:`${shortDate(r.week_start)}\n${fmt(r[key])} ${money?'บาท':'คดี'}`})),{left:100,width:450,height:34,decimals:money?1:0,unit:money?' ลบ.':'',color:money?'#628ba5':'#147f79'});}
function qualityText(r){return {missing:'ไม่มีตัวเลขคดี',standard:'ข้อมูลปกติ',caution:'มีหมายเหตุ',suspect_total:'ยอดรวมผิดปกติ',overlapping_period:'ช่วงเวลา 8 วันซ้อนกัน'}[r.quality];}
function renderOverview(rows){
 const valid=eligible(rows),series=safeRows(rows),cases=sum(valid,'acsc_cases'),loss=sum(valid,'acsc_loss_baht'),verdicts=sum(rows,'afnc_verdicts'),falseNews=sum(rows,'afnc_fake')+sum(rows,'afnc_distorted');
 const excluded=rows.filter(r=>r.acsc_reported&&!valid.includes(r)),missing=rows.filter(r=>!r.acsc_reported);
 let html=`<div class="kpis">${kpi('คดีที่รายงานในช่วงที่เลือก',valid.length?fmt(cases):'—','คดี',`ใช้ ${valid.length} สัปดาห์จาก ${rows.length} สัปดาห์ที่เลือก`)}${kpi('ความเสียหายรวมที่รายงาน',valid.length?million(loss):'—','ล้านบาท','รวมทั้งค่าที่ปัดเศษตามแหล่งข่าว')}${kpi('ความเสียหายเฉลี่ยต่อคดี',cases?fmt(loss/cases):'—','บาท','ผลรวมความเสียหาย ÷ ผลรวมคดี')}${kpi('สัดส่วนข่าวเท็จในคำตัดสิน',verdicts?fmt(100*falseNews/verdicts,1):'—','%',`${fmt(falseNews)} จาก ${fmt(verdicts)} คำตัดสิน AFNC`)}</div>`;
 html+=`<div class="notice ${$('include-flagged').checked?'danger':''}">${$('include-flagged').checked?'กำลังรวมยอดผิดปกติและช่วงเวลา 8 วัน หากอยู่ในช่วงที่เลือก ยอดรวมอาจถูกครอบงำโดยรายการเหล่านี้':'ค่าเริ่มต้นแยกยอดรวมผิดปกติและช่วงเวลา 8 วันออกจากตัวเลขคดี'} · ช่วงนี้แยกออก ${excluded.length} สัปดาห์ · ไม่มีตัวเลขคดี ${missing.length} สัปดาห์ · ไม่เติมค่าที่ขาดเป็นศูนย์</div>`;
 const trend=line(series,'acsc_cases','#147f79','จำนวนคดี')+line(series,'acsc_loss_baht','#628ba5','ความเสียหายรวม',{money:true})+line(series,'acsc_loss_per_case_baht','#e49a55','ความเสียหายต่อคดี',{ratio:true});
 let insight='เลือกช่วงที่มีตัวเลขคดีเพื่อเปรียบเทียบแนวโน้ม';
 if(valid.length){const a=[...valid].sort((a,b)=>b.acsc_cases-a.acsc_cases)[0],b=[...valid].sort((a,b)=>b.acsc_loss_baht-a.acsc_loss_baht)[0];insight=`คดีสูงสุด: <strong>${shortDate(a.week_start)} (${fmt(a.acsc_cases)} คดี)</strong> · ความเสียหายสูงสุด: <strong>${shortDate(b.week_start)} (${million(b.acsc_loss_baht)} ล้านบาท)</strong> — ${a.week_start===b.week_start?'เป็นสัปดาห์เดียวกัน':'เป็นคนละสัปดาห์'}ในช่วงที่เลือก`;
 const pairs=valid.slice(1).map((r,i)=>[valid[i],r]).filter(([a,b])=>(Date.parse(b.week_start)-Date.parse(a.week_start))/86400000===7);
 const mixed=pairs.filter(([a,b])=>b.acsc_cases<a.acsc_cases&&b.acsc_loss_per_case_baht>a.acsc_loss_per_case_baht);
 insight+=`<br>พบ ${mixed.length} คู่สัปดาห์ที่คดีลด แต่เสียหายต่อคดีเพิ่ม จาก ${pairs.length} คู่สัปดาห์ที่ต่อเนื่องและใช้ได้`;}
 html+=`<div class="grid">${card('จำนวนคดีกับความเสียหาย เคลื่อนไหวเหมือนกันไหม?','รายสัปดาห์ · แยกแกนตั้งตามหน่วย · คลิกจุดเพื่อดูรายละเอียด · เส้นขาดเมื่อไม่มีตัวเลขที่ใช้ได้',trend+`<div class="insight">${insight}</div>`,'Q1–Q2')}${card('สัปดาห์ไหนขึ้นอันดับสูงสุด?','Top 5 ในช่วงที่เลือก · การจัดอันดับสองด้านอาจให้ภาพต่างกัน',`<h3>จำนวนคดี</h3>${topWeeks(valid,'acsc_cases')}<h3 style="margin-top:30px">ความเสียหายรวม</h3>${topWeeks(valid,'acsc_loss_baht',true)}<p class="subtitle">อันดับคำนวณใหม่ตามช่วงเวลาและตัวเลือกคุณภาพข้อมูล</p>`,'Q3')}</div>`;
 html+=card('เจาะดูหนึ่งสัปดาห์','ดูข่าวและตัวเลขในช่วงเดียวกัน เพื่อสำรวจบริบท ไม่ใช่จับคู่ข่าวกับคดีโดยตรง',`<div class="week-picker"><label for="week-select">เลือกสัปดาห์</label><select id="week-select">${[...rows].reverse().map(r=>`<option value="${r.week_start}">${shortDate(r.week_start)}–${shortDate(r.week_end)}</option>`).join('')}</select></div><div id="week-detail"></div>`,'DETAIL');
 $('overview').innerHTML=html;
 if(rows.length){if(!rows.some(r=>r.week_start===selectedWeek))selectedWeek=valid.at(-1)?.week_start||rows.at(-1).week_start;$('week-select').value=selectedWeek;$('week-select').onchange=()=>{selectedWeek=$('week-select').value;renderWeek();};renderWeek();}
}
function renderWeek(){const r=D.weekly.find(x=>x.week_start===selectedWeek);if(!r)return;const list=NEWS.filter(n=>n.week_start===r.week_start),excluded=r.exclude_default&&!$('include-flagged').checked;
 $('week-detail').innerHTML=`<div class="mini-grid"><div class="mini">คดีที่แหล่งข่าวรายงาน${excluded?' (แยกออกจากยอดรวม)':''}<b>${fmt(r.acsc_cases)}</b></div><div class="mini">ความเสียหายที่แหล่งข่าวรายงาน (ล้านบาท)<b>${r.acsc_loss_baht===null?'—':million(r.acsc_loss_baht)}</b></div><div class="mini">คำตัดสิน AFNC ทั้งหมด<b>${fmt(r.afnc_verdicts)}</b></div></div><span class="tag ${r.quality==='standard'?'':'warn'}">${qualityText(r)}</span>${r.acsc_source_url?` <a class="download" href="${esc(r.acsc_source_url)}" target="_blank" rel="noopener">แหล่งข่าวสถิติคดี ↗</a>`:''}${r.acsc_flag?`<p class="subtitle">${esc(r.acsc_flag)}</p>`:''}${r.acsc_reported?`<p class="subtitle">ประเภทที่มีคดีมากที่สุด: ${esc(r.acsc_top_type_th||'ไม่ระบุ')}<br>ประเภทที่เสียหายสูงที่สุด: ${esc(r.acsc_highest_loss_type_th||'ไม่ระบุ')}</p>`:''}<div class="table-wrap"><table><thead><tr><th>วันที่เผยแพร่</th><th>ข่าวที่ AFNC ตรวจสอบ (${list.length} รายการ)</th><th>ผลตัดสิน</th></tr></thead><tbody>${list.slice(0,100).map(n=>`<tr><td>${shortDate(n.date)}</td><td><a href="${esc(n.url)}" target="_blank" rel="noopener">${esc(n.title)} ↗</a></td><td>${{Fake:'ข่าวปลอม',Distorted:'บิดเบือน',True:'ข่าวจริง'}[n.verdict_en]}</td></tr>`).join('')}</tbody></table>${!list.length?empty('ไม่มีคำตัดสินข่าวในสัปดาห์นี้'):''}</div>`;
}
function renderNews(rows){
 const weekSet=new Set(rows.map(r=>r.week_start)),group=new Map();
 for(const r of D.categories.filter(r=>weekSet.has(r.week_start))){if(!group.has(r.category))group.set(r.category,{label:catNames[r.category]||r.category,total:0,false:0});const g=group.get(r.category);g.total+=r.fake+r.distorted+r.true;g.false+=r.fake+r.distorted;}
 const g=[...group.values()],byCount=[...g].sort((a,b)=>b.false-a.false),byShare=[...g].sort((a,b)=>b.false/b.total-a.false/a.total),monthlyRows=monthly(rows),v=sum(rows,'afnc_verdicts'),f=sum(rows,'afnc_fake'),d=sum(rows,'afnc_distorted');
 let html=`<div class="kpis">${kpi('คำตัดสินทั้งหมด',fmt(v),'รายการ','กรองเฉพาะโพสต์ประเภท Verdict')}${kpi('ข่าวปลอม',fmt(f),'รายการ','คำตัดสิน Fake ของ AFNC')}${kpi('ข่าวบิดเบือน',fmt(d),'รายการ','คำตัดสิน Distorted ของ AFNC')}${kpi('ข่าวจริง',fmt(sum(rows,'afnc_true')),'รายการ','คำตัดสิน True ของ AFNC')}</div>`;
 html+=`<div class="notice neutral">จำนวนเหล่านี้สะท้อนเรื่องที่ AFNC เลือกตรวจสอบและเผยแพร่ ไม่ใช่ปริมาณข่าวปลอมทั้งหมดในสังคม · สัดส่วนข่าวเท็จ = (Fake + Distorted) ÷ คำตัดสินทั้งหมด</div>`;
 html+=`<div class="grid equal">${card('หมวดไหนมีข่าวเท็จมากที่สุด?','จำนวน Fake + Distorted ในช่วงที่เลือก',bars(byCount.map(r=>({label:r.label,value:r.false,tip:`${r.label}\nข่าวเท็จ ${fmt(r.false)} จาก ${fmt(r.total)} คำตัดสิน`}))), 'Q4A')}${card('หมวดไหนมีสัดส่วนข่าวเท็จสูงที่สุด?','เรียงตามเปอร์เซ็นต์ · อ่านจำนวนที่ตรวจสอบประกอบเสมอ',bars(byShare.map(r=>({label:r.label,value:100*r.false/r.total,tip:`${r.label}\n${fmt(100*r.false/r.total,1)}% · ${fmt(r.false)}/${fmt(r.total)} รายการ`})),{percent:true,color:'#628ba5',unit:'%'}),'Q4B')}</div>`;
 if(g.length)html+=`<div class="insight" style="margin-bottom:20px">อันดับตามจำนวน: <strong>${esc(byCount[0].label)}</strong> (${fmt(byCount[0].false)} รายการ) · อันดับตามสัดส่วน: <strong>${esc(byShare[0].label)}</strong> (${fmt(100*byShare[0].false/byShare[0].total,1)}% จาก ${fmt(byShare[0].total)} คำตัดสิน)${byShare[0].total<30?' · ฐานจำนวนน้อย ควรตีความอย่างระมัดระวัง':''}</div>`;
 html+=card('ข่าวเท็จเพิ่ม เพราะตรวจสอบมากขึ้นหรือเปล่า?','รวมรายเดือนตามวันเริ่มสัปดาห์ ไม่ใช่ยอดตามวันปฏิทิน · เดือนต้นและท้ายอาจมีข้อมูลเพียงบางสัปดาห์',stacked(monthlyRows)+`<div class="table-wrap"><table><thead><tr><th>เดือนของสัปดาห์</th><th>คำตัดสินทั้งหมด</th><th>ข่าวเท็จ</th><th>สัดส่วนข่าวเท็จ</th></tr></thead><tbody>${monthlyRows.map(m=>{const total=m.fake+m.distorted+m.true;return `<tr><td>${thMonth(m.month)}</td><td>${fmt(total)}</td><td>${fmt(m.fake+m.distorted)}</td><td>${total?fmt(100*(m.fake+m.distorted)/total,1)+'%':'—'}</td></tr>`;}).join('')}</tbody></table></div>`,'Q5');
 $('news').innerHTML=html;
}
function renderAI(){
 const years=[...new Set(D.ai.map(r=>r.year))].sort((a,b)=>a-b);
 $('ai').innerHTML=`<div class="notice neutral">ส่วนนี้เป็นบริบทจากฐานเหตุการณ์ AI หลายประเทศ ไม่เชื่อมเหตุการณ์เข้ากับคดีไทย และไม่ใช่สถิติความเสี่ยงของโลกทั้งหมด · ใช้ AIID snapshot ${D.ai_snapshot.slice(0,4)}-${D.ai_snapshot.slice(4,6)}-${D.ai_snapshot.slice(6,8)}</div><div class="ai-filters"><label>ปีเหตุการณ์ตั้งแต่ <select id="ai-start">${years.map(y=>`<option ${y===2015?'selected':''}>${y}</option>`).join('')}</select></label><label>ถึง <select id="ai-end">${years.map(y=>`<option ${y===years.at(-1)?'selected':''}>${y}</option>`).join('')}</select></label><span class="kpi-note">ตัวกรองนี้ใช้กับ AIID เท่านั้น</span></div><div id="ai-content"></div>`;
 $('ai-start').onchange=renderAIContent;$('ai-end').onchange=renderAIContent;renderAIContent();
}
function renderAIContent(){
 const start=+$('ai-start').value,end=+$('ai-end').value;
 if(start>end){$('ai-content').innerHTML=empty('ปีเริ่มต้นต้องไม่มากกว่าปีสิ้นสุด');return;}
 const rows=D.ai.filter(r=>r.year>=start&&r.year<=end),classified=rows.filter(r=>r['Risk Domain']),groups=new Map();
 for(const r of classified){const k=r['Risk Domain'];groups.set(k,(groups.get(k)||0)+1);}
 const mis=classified.filter(r=>r['Risk Domain'].toLowerCase().includes('misinformation'));
 const ranked=[...groups.entries()].sort((a,b)=>b[1]-a[1]);
 const cases=mis.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3);
 $('ai-content').innerHTML=`<div class="kpis">${kpi('เหตุการณ์ในช่วงที่เลือก',fmt(rows.length),'เหตุการณ์','นับ Incident ID ไม่ซ้ำ')}${kpi('มีการจัดหมวดความเสี่ยง',fmt(classified.length),'เหตุการณ์',`${rows.length?fmt(100*classified.length/rows.length,1):'—'}% ของเหตุการณ์ที่เลือก`)}${kpi('หมวด Misinformation',fmt(mis.length),'เหตุการณ์','ใช้หมวดที่ระบุในฐานข้อมูล')}${kpi('สัดส่วน Misinformation',classified.length?fmt(100*mis.length/classified.length,1):'—','%','ตัวหารเฉพาะเหตุการณ์ที่มี Risk Domain')}</div><div class="grid">${card('ความเสี่ยงด้านข้อมูลเท็จอยู่ตรงไหนในฐานนี้?','นับตาม Risk Domain · ชื่อหมวดแสดงตามข้อมูลต้นทาง',bars(ranked.map(([k,v])=>({label:riskNames[k]||k,value:v,tip:`${k}\n${v} เหตุการณ์`,color:k.toLowerCase().includes('misinformation')?'#147f79':'#8ca8b7'})),{left:250})+`<div class="insight">ยังไม่ระบุหมวด <strong>${fmt(rows.length-classified.length)} เหตุการณ์</strong> ไม่ถือว่าไม่มีความเสี่ยง<br>จำนวนที่บันทึกขึ้นกับการรายงานข่าวและการรวบรวมของฐานข้อมูล</div>`,'Q6')}${card('ตัวอย่างเหตุการณ์ในหมวดข้อมูลเท็จ','รายการล่าสุดตามวันเกิดเหตุในช่วงที่เลือก · ข้อความสรุปภาษาอังกฤษตามต้นทาง',cases.length?cases.map(r=>`<div class="ai-case"><span class="tag">${shortDate(r.date)}</span><h3 style="margin-top:9px">${esc(r.title)}</h3><p>${esc(r.description)}</p><a href="https://incidentdatabase.ai/cite/${encodeURIComponent(r['Incident ID'])}/" target="_blank" rel="noopener">อ่านเหตุการณ์ #${esc(r['Incident ID'])} ↗</a></div>`).join(''):empty(),'CASES')}</div><div class="notice">ไม่ได้ทำแผนที่เหตุการณ์ AI เพราะข้อมูลประเทศไม่ครบ และไม่ได้ถือว่าเหตุการณ์ที่ไม่ระบุ TH คือเหตุการณ์นอกไทยทั้งหมด</div>`;
}
function renderQuality(){
 const r=D.report,c=r.counts,flagged=D.weekly.filter(w=>w.acsc_flag),missing=D.weekly.filter(w=>!w.acsc_reported&&w.week_start>='2025-11-09');
 $('quality').innerHTML=`<div class="kpis">${kpi('ตารางหลัก',fmt(c.weekly_rows),'สัปดาห์','ตรวจช่วงสัปดาห์ต่อเนื่องและคีย์ไม่ซ้ำ')}${kpi('ผลเทียบยอด AFNC',fmt(r.panel_reconciliation_differences),'จุดต่าง','คำนวณใหม่จากโพสต์แล้วเทียบยอดเดิม')}${kpi('สัปดาห์คดีที่มีข้อมูล',fmt(c.acsc_reported_weeks),'สัปดาห์',`ค่าเริ่มต้นนำมาคำนวณ ${c.acsc_default_included} สัปดาห์`)}${kpi('ข้อมูลต้นฉบับ','คงเดิม','','สร้างไฟล์สะอาดแยกจาก dataset/')}</div>`;
 $('quality').innerHTML+=card('ข้อมูลเชื่อมกันอย่างไร?','weekly_panel เป็นแกนหลักของสถานการณ์ไทย ส่วน AIID เป็นบริบทแยก',`<div class="flow"><span>AFNC · โพสต์<br>สรุปเป็น week_start</span><b>→</b><span>weekly_panel · สัปดาห์<br>เทียบยอดเดิมทุกสัปดาห์</span><b>←</b><span>ACSC · รายงานรายสัปดาห์<br>คีย์สัปดาห์เพื่อวิเคราะห์</span></div><div class="flow"><span>AIID · Incident ID ไม่ซ้ำ<br>snapshot เดียวล่าสุดในโปรเจค</span><b>→</b><span>หน้า AI · หมวดความเสี่ยง<br>ไม่ JOIN กับยอดคดีไทย</span></div><div class="method">AFNC + ACSC + AIID เป็น 3 แหล่งข้อมูล ส่วน weekly_panel เป็นตารางรวมของสองแหล่งแรก<br>ไฟล์สะอาดเก็บเฉพาะคอลัมน์ที่ใช้วิเคราะห์ รายละเอียดเนื้อหาเต็มยังอยู่ในไฟล์ต้นฉบับ<br>ข่าว AFNC ระบุขอบเขตแหล่งตรวจสอบไทย ไม่ได้ยืนยันว่าทุกเรื่องเกิดในประเทศไทย</div>`);
 $('quality').innerHTML+=card('รายการคดีที่ต้องอ่านหมายเหตุ','แถวเหล่านี้ยังเก็บไว้ครบ การแยกออกเป็นตัวเลือกวิเคราะห์ ไม่ใช่การแก้ตัวเลขต้นทาง',`<div class="table-wrap"><table><thead><tr><th>สัปดาห์เพื่อวิเคราะห์</th><th>วันที่ต้นทาง</th><th>สถานะ</th><th>การจัดการและเหตุผล</th></tr></thead><tbody>${flagged.map(w=>`<tr><td>${shortDate(w.week_start)}</td><td>${shortDate(w.acsc_source_week_start)}<br>${w.acsc_days} วัน</td><td><span class="tag ${w.exclude_default?'red':'warn'}">${qualityText(w)}</span></td><td>${w.exclude_default?'แยกจากยอดคดีเป็นค่าเริ่มต้น':'ยังรวมยอด แต่แสดงคำเตือน'}<br>${esc(w.acsc_flag)}<br><a href="${esc(w.acsc_source_url)}" target="_blank" rel="noopener">แหล่งข่าว ↗</a></td></tr>`).join('')}</tbody></table></div>`);
 $('quality').innerHTML+=`<div class="grid equal">${card('สัปดาห์ที่ไม่มีตัวเลขคดี','ภายในช่วงตั้งแต่เริ่มเก็บ ACSC ถึงปลายตารางหลัก',`<ul class="method">${missing.map(w=>`<li>${shortDate(w.week_start)}–${shortDate(w.week_end)}</li>`).join('')}</ul><p class="subtitle">เก็บเป็นค่าว่าง ไม่แทนด้วยศูนย์ เส้นกราฟเว้นช่อง ไม่ลากเชื่อมข้าม</p>`)}${card('วิธีอ่านผลรวมและสัดส่วน','กติกาที่ใช้ทุกกราฟ',`<ul class="method"><li>ความเสียหายต่อคดี = ผลรวมความเสียหาย ÷ ผลรวมคดี</li><li>สัดส่วนข่าวเท็จ = (Fake + Distorted) ÷ คำตัดสินทั้งหมด</li><li>เดือนจัดตาม week_start ไม่ใช่เดือนปฏิทินของทุกโพสต์</li><li>คดีเป็นยอดแจ้งความที่รวบรวมจากข่าวแถลง</li><li>ค่าความเสียหายบางสัปดาห์เป็นตัวเลขปัดเศษ</li><li>ไม่ใช้ยอดวิว AFNC เปรียบเทียบข้ามอายุโพสต์</li><li>ไม่แปลงคดีเป็นจำนวนผู้เสียหาย และไม่สรุปเหตุและผล</li></ul>`)}</div>`;
 $('quality').innerHTML+=card('ดาวน์โหลดข้อมูลที่จัดระเบียบแล้ว','ไฟล์ CSV เป็น UTF-8 พร้อม BOM สำหรับเปิดใน Excel · ดูวิธีทำซ้ำใน README',`<a class="download" href="../data/processed/weekly_panel_clean.csv" download>ตารางหลักสะอาด ↓</a><a class="download" href="../data/processed/afnc_category_weekly.csv" download>หมวดข่าวรายสัปดาห์ ↓</a><a class="download" href="../data/processed/acsc_weekly_clean.csv" download>คดีพร้อมสถานะคุณภาพ ↓</a><a class="download" href="../data/processed/ai_incidents_clean.csv" download>เหตุการณ์ AI ↓</a><a class="download" href="../data/processed/quality_report.json" download>รายงานคุณภาพ ↓</a><details><summary>ไฟล์ต้นทางและ SHA-256 สำหรับตรวจว่าไม่ถูกแก้ไข</summary><div class="table-wrap"><table><tbody>${r.inputs.map(i=>`<tr><td>${esc(i.file)}</td><td style="word-break:break-all">${i.sha256}</td></tr>`).join('')}</tbody></table></div></details>`);
}
function render(){
 const bad=$('start').value>$('end').value||!$('start').value||!$('end').value;$('error').hidden=!bad;if(bad){$('error').textContent='กรุณาเลือกวันที่เริ่มต้นไม่เกินวันที่สิ้นสุด';$('overview').innerHTML=empty('รอเลือกช่วงวันที่ถูกต้อง');$('news').innerHTML=empty('รอเลือกช่วงวันที่ถูกต้อง');$('filter-caption').textContent='ยังไม่ได้คำนวณผลลัพธ์สำหรับช่วงวันที่นี้';return;}
 const rows=getRows();$('filter-caption').textContent=rows.length?`เลือก ${rows.length} สัปดาห์ · ตั้งแต่ ${shortDate(rows[0].week_start)} ถึง ${shortDate(rows.at(-1).week_end)} · กรองด้วยวันเริ่มสัปดาห์ (อาทิตย์) · ใช้ปี ค.ศ.`:'ไม่มีสัปดาห์ในช่วงที่เลือก';
 renderOverview(rows);renderNews(rows);
}
const titles={overview:['01 / THAILAND WEEKLY MONITOR','คดีมาก ≠ เสียหายหนัก','อ่านจำนวนคดีควบคู่กับความเสียหาย และบริบทข่าวที่ถูกตรวจสอบในช่วงเดียวกัน'],news:['02 / FACT-CHECKING PATTERNS','มากที่สุด กับสัดส่วนสูงที่สุด','แยกปริมาณการตรวจสอบออกจากสัดส่วนผลตัดสิน เพื่ออ่านข้อมูล AFNC อย่างตรงความหมาย'],ai:['03 / AI INCIDENT CONTEXT','ข้อมูลเท็จ ในฐานเหตุการณ์ AI','มองหมวดความเสี่ยงและกรณีที่บันทึกไว้ พร้อมบอกส่วนที่ยังไม่ถูกจัดหมวด'],quality:['04 / DATA NOTES','ก่อนเชื่อตัวเลข อ่านที่มาของมัน','ตรวจการเชื่อมข้อมูล ค่าที่ขาด ช่วงเวลาผิดปกติ และกติกาการคำนวณ']};
function showTab(name){if(!titles[name])name='overview';tab=name;document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==name);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));['eyebrow','page-title','page-lead'].forEach((id,i)=>$(id).textContent=titles[name][i]);$('thai-filters').hidden=name==='ai'||name==='quality';$('thai-filters').style.display=name==='ai'||name==='quality'?'none':'';$('filter-caption').hidden=name==='ai'||name==='quality';$('error').hidden=true;history.replaceState(null,'','#'+name);}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>showTab(b.dataset.tab));
['start','end','include-flagged'].forEach(id=>$(id).addEventListener('change',render));
$('shared').onclick=()=>{$('start').value='2025-11-09';$('end').value='2026-10-18';render();};
$('all').onclick=()=>{$('start').value='2018-12-30';$('end').value='2026-10-25';render();};
document.addEventListener('click',e=>{const point=e.target.closest('[data-week]');if(point){selectedWeek=point.dataset.week;$('week-select').value=selectedWeek;renderWeek();$('week-select').scrollIntoView({behavior:'smooth',block:'center'});}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-week]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
const tooltip=$('tooltip');
function showTip(el,x,y){tooltip.textContent=el.dataset.tip;tooltip.hidden=false;tooltip.style.left=Math.min(x+12,innerWidth-tooltip.offsetWidth-12)+'px';tooltip.style.top=Math.max(8,Math.min(y+12,innerHeight-tooltip.offsetHeight-12))+'px';}
document.addEventListener('pointermove',e=>{const el=e.target.closest('[data-tip]');if(!el){tooltip.hidden=true;return;}showTip(el,e.clientX,e.clientY);});
document.addEventListener('focusin',e=>{if(e.target.matches('[data-tip]')){const r=e.target.getBoundingClientRect();showTip(e.target,r.left,r.bottom);}});
document.addEventListener('focusout',()=>tooltip.hidden=true);
render();renderAI();renderQuality();showTab(location.hash.slice(1));
